def _sum_rent_amounts(text: str) -> Optional[float]:
    """Sum monthly rent figures from rent-roll style lines."""
    total = 0.0
    count = 0
    for line in text.splitlines():
        low = line.lower()
        if "rent" in low or "monthly" in low:
            amt = _money(line)
            if amt is not None and 100 < amt < 5_000_000:
                total += amt
                count += 1
    return total if count >= 3 else None

arguments.newString:
def _sanitize_value_amount(val: Optional[float], *, min_amount: float = 100_000) -> Optional[float]:
    """Drop implausibly small property values; ``min_amount`` itself is valid.

    Mirrors ``cre_qualification.facts.resolve_appraisal_value``, which accepts
    values ``>= 100_000``.
    """
    if val is None:
        return None
    try:
        f = float(val)
    except (TypeError, ValueError):
        return None
    return f if f >= min_amount else None

